<?php require __DIR__.'/../koneksi.php';if(!empty($_SESSION['admin_id']))redirect('index.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$user=trim($_POST['username']??'');$pass=$_POST['password']??'';$st=$koneksi->prepare('SELECT id_user,password_hash FROM users WHERE username=? AND role="admin"');$st->bind_param('s',$user);$st->execute();$a=$st->get_result()->fetch_assoc();if($a&&password_verify($pass,$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=$a['id_user'];redirect('index.php');}$error='Username atau password salah.';}$base='../';$page_title='Login Admin';require __DIR__.'/../partials/header.php';?><main class="container py-5" style="max-width:480px"><div class="soft-card p-4"><h3>Login Admin</h3><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label class="form-label">Username</label><input name="username" class="form-control mb-3" required><label class="form-label">Password</label><input name="password" type="password" class="form-control mb-3" required><button class="btn btn-pink">Masuk</button></form><p class="small mt-3 text-muted">Buat akun admin melalui setup_admin.php (sekali saja).</p></div></main><?php require __DIR__.'/../partials/footer.php';?>
